    # Initialize tracing eagerly so OTel spans (`@traced(...)`) ship from the
    # first request. Without this, the tracer provider is configured lazily on
    # first copilot-agent invocation, so any request that hits a non-copilot
    # path before then (e.g. workflow runs from the caching benchmark) records
    # no-op spans. Uvicorn's `--reload` resets module-level state on edits, so
    # the lazy path also fails after every code change in dev.
    ensure_tracing_initialized()

    # Auto-bootstrap SQLite database on first server start.
    # Re-raise on failure — a server with no tables/org/API key is
    # useless and would produce confusing 401s on every request.
    if settings.is_sqlite():
        await _bootstrap_sqlite()

    if forge_app.api_app_startup_event:
        LOG.info("Calling api app startup event")
        try:
            await forge_app.api_app_startup_event(fastapi_app)
        except Exception:
            LOG.exception("Failed to execute api app startup event")

    try:
        await load_custom_llm_configs_from_database(forge_app.DATABASE)
    except Exception:
        LOG.exception("Failed to load custom LLM configs")

    # Close browser sessions left active by a previous process
    try:
        await forge_app.PERSISTENT_SESSIONS_MANAGER.cleanup_stale_sessions()
    except Exception:
        LOG.exception("Failed to clean up stale browser sessions")

    # Reap idle/abandoned persistent sessions on a timer so their in-process Chromium +
    # record_video ffmpeg encoders don't leak (nothing else closes a session once it stops renewing).
    try:
        forge_app.PERSISTENT_SESSIONS_MANAGER.start_reaper()
    except Exception:
        LOG.exception("Failed to start persistent browser session reaper")

    # Start cleanup scheduler if enabled
    cleanup_task = start_cleanup_scheduler()
    if cleanup_task:
        LOG.info("Cleanup scheduler started")

    start_temp_artifact_sweep()

    workflow_schedule_task = start_workflow_schedule_scheduler()
    if workflow_schedule_task:
        LOG.info("Workflow schedule scheduler started")

    # Start MCP sub-application lifespan if mounted. Starlette Mount does NOT
    # forward lifespan events to sub-apps, so we must enter the MCP app's
    # lifespan here. This initializes the streamable-http session manager's
    # task group which is required for handling MCP requests.
    mcp_app = getattr(fastapi_app.state, "mcp_starlette_app", None)
    if mcp_app:
        async with mcp_app.lifespan(mcp_app):
            LOG.info("MCP remote server lifespan started")
            yield
        LOG.info("MCP remote server lifespan stopped")
    else:
        yield

    # Stop cleanup scheduler
    await stop_workflow_schedule_scheduler()
    await stop_cleanup_scheduler()
